ALTER Procedure [dbo].[ForCpy_GetLabRt] 
	(@mCmCd varchar(8), @mLabMCd varchar(5), @mLabSCd varchar(8), @mOpt varchar(1), 
	@mGldAsWt int, @mCmCtg char(1), @mLabQw varchar(max), @mOldGldAsWt int = 0, 
	@mWtRngChg varchar(2) output, @mCmCurCd varchar(8), @mCmLkUpLabRt varchar(8),@MRT INT OUTPUT)
	
as
begin
declare @wRmRt as decimal(10,3)
declare @wRt varchar(8)
declare @wInc decimal(10,4), @wCommStr nvarchar(max)
declare @wCommQwStr varchar(max)
declare @wCnd varchar(100), @wCnd1 varchar(100), @wCnd2 varchar(100)
declare @wLabQw varchar(max)
declare @wCmSeekZSelfRt bit
  If (@mOpt <> 'C') And (@mOpt <> 'S') 
	select 0
 
  select @wRt = case when @mOpt = 'S' then 'LrSalRt' else 'LrCstRt' end

  If @mCmCurCd='' 
  begin
	select @mCmCurCd = CmCurCd from CustMst where CmCtg= @mCmCtg  and CmCd= @mCmCd 
  end
  --6.1-13 seek from custmst is removed  
  --If @mCmLkUpLabRt = '' 
  --begin
  --  select @mCmLkUpLabRt = CmLkUpLabRt from CustMst where CmCtg= @mCmCtg and CmCd= @mCmCd
  --End
  
  select @wCmSeekZSelfRt = 1 where exists (Select 'x' from CustMst where CmCtg= @mCmCtg and CmCd= @mCmCd and CmSeekZSelfRt='Y')
  
  If @mCmCtg = 'S' And @mOpt = 'C' select @mCmCtg = 'C'
  
  select @wCommStr = 'select ' + @wRt + ' from LabRt where LrMCd=''' + @mLabMCd + ''' and LrSCd=''' + @mLabSCd + ''' and LrCmCurCd=''' + @mCmCurCd + '''' 
  
  select @wCnd = ' and LrFrWt<= ' + convert(varchar,@mGldAsWt) + ' and LrToWt>= ' + convert(varchar,@mGldAsWt) 
 
  If @mLabMCd = 'GHC' select @wCnd = ' and 1=1 '
  declare @ctselfcocd varchar(5) 
  declare @ctSelfCmCd varchar(5) 
  declare @GetLabRt nvarchar(max)
  
  select @ctselfcocd='ZZZ'
  select @ctSelfCmCd= 'ZSELF'
  
  If @mOpt = 'S' 
	begin 
	  select @wInc = RrSalRt from RmRt where RrTcTyp= 'INL' and RrLabMcd= @mLabMCd and RrCmCtg= @mCmCtg and RrCmCd= @mCmCd 
	  select @wInc =isnull(@wInc,0)
        
      If @mCmCtg = 'C' Or @mCmCtg = 'S' 								  
		select @GetLabRt ='select @wRmRt=IsNull((' + @wCommStr + 'and LrCmCtg= ''P'' and LrCmCd=''' + @mCmLkUpLabRt + '''' + @wCnd + '), 
							IsNull((' + @wCommStr + ' and LrCmCtg=''' + @mCmCtg + ''' and LrCmCd=''' + @mCmCd + '''' + @wCnd + '),' + 	 
							case when (@wCmSeekZSelfRt =1 Or @mOpt = 'C') then 
							'IsNull((' + @wCommStr + ' and LrCmCtg=''' + @mCmCtg + ''' and LrCmCd=''' + @ctSelfCmCd + '''' + @wCnd + ')
							* (1 +' + CONVERT(varchar,@wInc) + ' / 100)	,0)' else '0' end + '))'							 
	  Else If @mCmCtg = 'T' 
		select @GetLabRt = 'Select @wRmRt=  IsNull((' + @wCommStr + ' and LrCmCtg= ''T'' and LrCmCd=''' + @mCmCd + '''' + @wCnd + '),0)'
	end 	
  Else	
  begin
		select @wInc =isnull(@wInc,0)
      select @GetLabRt  = 'Select @wRmRt=IsNull ((' + @wCommStr + ' and LrCmCtg= ''P'' and LrCmCd=''' + @mCmLkUpLabRt + '''' + @wCnd + 
							' and LrCstRt <> 0 ), 
							IsNull((' + @wCommStr + ' and LrCmCtg=''' + @mCmCtg + ''' and LrCmCd=''' + @mCmCd + '''' + @wCnd + 
							' and LrCstRt <> 0 ),' +
							case when (@wCmSeekZSelfRt=1 Or @mOpt = 'C') then 
							'IsNull((' + @wCommStr + ' and LrCmCtg=''' + @mCmCtg + ''' and LrCmCd=''' + @ctSelfCmCd + '''' + @wCnd + 
							' and LrCstRt <> 0 ) * (1 +' + CONVERT(varchar,@wInc) + '/ 100) ,0)' else '0' end + '))'
  
   	end

      
    If (@mLabQw<>'') Or (@mWtRngChg<>'') 
    begin
		select @wCommQwStr = 'Select LrQw from LabRt where LrMCd=''' + @mLabMCd + ''' and LrSCd=''' + @mLabSCd + ''' and LrCmCurCd=''' + @mCmCurCd + ''''
				
		If @mOpt = 'S' 
		begin    
		  If @mCmCtg = 'C' Or @mCmCtg = 'S' 
		  begin
			select @wLabQw =LrQw from LabRt where LrMCd=@mLabMCd and LrSCd=@mLabSCd and LrCmCurCd=@mCmCurCd and LrCmCtg='P' 
							and LrCmCd= @mCmLkUpLabRt and LrFrWt<= convert(varchar,@mGldAsWt) and LrToWt>= convert(varchar,@mGldAsWt)
			if (@wLabQw='' or @wLabQw is null) 
			select @wLabQw =LrQw from LabRt where LrMCd=@mLabMCd and LrSCd=@mLabSCd and LrCmCurCd=@mCmCurCd and LrCmCtg=@mCmCtg 
							and LrCmCd=@mCmCd and LrFrWt<= convert(varchar,@mGldAsWt) and LrToWt>= convert(varchar,@mGldAsWt)
			if (@wLabQw='' or @wLabQw is null) 
				begin
				if @wCmSeekZSelfRt=1 Or @mOpt = 'C'  
				select @wLabQw = LrQw from LabRt where LrMCd=@mLabMCd and LrSCd=@mLabSCd and LrCmCurCd=@mCmCurCd and LrCmCtg=@mCmCtg 
								and LrCmCd=@ctSelfCmCd and LrFrWt<= convert(varchar,@mGldAsWt) and LrToWt>= convert(varchar,@mGldAsWt) 
				end			
			end	
		  Else If @mCmCtg = 'T' 
			select @wLabQw = LrQw from LabRt where LrMCd=@mLabMCd and LrSCd=@mLabSCd and LrCmCurCd=@mCmCurCd and LrCmCtg='T' 
							and LrCmCd=@mCmCd and LrFrWt<= convert(varchar,@mGldAsWt) and LrToWt>= convert(varchar,@mGldAsWt) 
		end
		Else If @wCmSeekZSelfRt=1 Or @mOpt = 'C' 
		  select @wLabQw = LrQw from LabRt where LrMCd=@mLabMCd and LrSCd=@mLabSCd and LrCmCurCd=@mCmCurCd and LrCmCtg= @mCmCtg  
							and LrCmCd= @ctSelfCmCd and LrFrWt<= convert(varchar,@mGldAsWt) and LrToWt>= convert(varchar,@mGldAsWt) 
										
	end    
	select @wLabQw =ISNULL(@wLabQw ,'')			

	If @mLabQw<>'' select @mLabQw = @wLabQw                               	
	
	If @mWtRngChg<>'' 
	begin
	  If @wLabQw = 'Q' Or @wLabQw = 'W' 	  
	  begin
		select @wCommQwStr = 'Select LrCmCtg, LrCmCd,LrMCd, LrSCd, LrFrWt, LrToWt from LabRt where LrMCd=''' + @mLabMCd + ''' and 
								LrSCd=''' + @mLabSCd + ''' and LrCmCurCd=''' + @mCmCurCd + '''' 
		select @wCnd1 = ' and LrFrWt<= ' + convert(varchar,@mOldGldAsWt) + ' and LrToWt>= ' + convert(varchar,@mOldGldAsWt) 
		select @wCnd2 = ' and LrFrWt<= ' + convert(varchar,@mGldAsWt) + ' and LrToWt>= ' + convert(varchar,@mGldAsWt)
		
		Select LrCmCtg, LrCmCd,LrMCd, LrSCd, LrFrWt, LrToWt into #wRsOldLabRt from LabRt where 1=2
		Select LrCmCtg, LrCmCd,LrMCd, LrSCd, LrFrWt, LrToWt into #wRsNewLabRt from LabRt where 1=2
		
	    If @mOpt = 'S' 
		  If @mCmCtg = 'C' Or @mCmCtg = 'S' 			
		  begin	
			declare @wOldCnt  int
			declare @wNewCnt  int
			insert into #wRsOldLabRt
			Select LrCmCtg, LrCmCd,LrMCd, LrSCd, LrFrWt, LrToWt  from LabRt 
					where LrMCd=@mLabMCd and LrSCd=@mLabSCd and LrCmCurCd=@mCmCurCd 
					and LrCmCtg= 'P' and LrCmCd=@mCmLkUpLabRt and LrFrWt<= convert(varchar,@mOldGldAsWt) and LrToWt>= convert(varchar,@mOldGldAsWt) 
		  	select	@wOldCnt= COUNT(*) from #wRsOldLabRt 
			
			if @wOldCnt =0 
			begin
				insert into #wRsOldLabRt 
				Select LrCmCtg, LrCmCd,LrMCd, LrSCd, LrFrWt, LrToWt  from LabRt 
					where LrMCd=@mLabMCd and LrSCd=@mLabSCd and LrCmCurCd=@mCmCurCd 
					and LrCmCtg=@mCmCtg and LrCmCd=@mCmCd and LrFrWt<= convert(varchar,@mOldGldAsWt) and LrToWt>= convert(varchar,@mOldGldAsWt) 
				select	@wOldCnt= COUNT(*) from #wRsOldLabRt 
			end
			
			if @wOldCnt=0 
			begin
				insert into #wRsOldLabRt 
				Select LrCmCtg, LrCmCd,LrMCd, LrSCd, LrFrWt, LrToWt from LabRt 
					where LrMCd=@mLabMCd and LrSCd=@mLabSCd and LrCmCurCd=@mCmCurCd 
					and LrCmCtg=@mCmCtg and LrCmCd=@ctSelfCmCd and LrFrWt<= convert(varchar,@mOldGldAsWt) and LrToWt>= convert(varchar,@mOldGldAsWt) 
				select	@wOldCnt= COUNT(*) from #wRsOldLabRt 
			end

			insert into #wRsNewLabRt
			Select LrCmCtg, LrCmCd,LrMCd, LrSCd, LrFrWt, LrToWt  from LabRt 
				where LrMCd=@mLabMCd and LrSCd=@mLabSCd and LrCmCurCd=@mCmCurCd 
				and LrCmCtg= 'P' and LrCmCd=@mCmLkUpLabRt and LrFrWt<= convert(varchar,@mGldAsWt) and LrToWt>= convert(varchar,@mGldAsWt) 
			select	@wNewCnt= COUNT(*) from #wRsNewLabRt 
	
			if @wNewCnt =0 
			begin
			insert into #wRsNewLabRt 
				Select LrCmCtg, LrCmCd,LrMCd, LrSCd, LrFrWt, LrToWt  from LabRt 
				where LrMCd=@mLabMCd and LrSCd=@mLabSCd and LrCmCurCd=@mCmCurCd 
				and LrCmCtg=@mCmCtg and LrCmCd=@mCmCd and LrFrWt<= convert(varchar,@mGldAsWt) and LrToWt>= convert(varchar,@mGldAsWt) 
			select	@wNewCnt= COUNT(*) from #wRsNewLabRt 
			end
			
			if @wNewCnt=0 
			begin
			insert into #wRsNewLabRt 
				Select LrCmCtg, LrCmCd,LrMCd, LrSCd, LrFrWt, LrToWt from LabRt 
				where LrMCd=@mLabMCd and LrSCd=@mLabSCd and LrCmCurCd=@mCmCurCd 
				and LrCmCtg=@mCmCtg and LrCmCd=@ctSelfCmCd and LrFrWt<= convert(varchar,@mGldAsWt) and LrToWt>= convert(varchar,@mGldAsWt) 
			select	@wNewCnt= COUNT(*) from #wRsNewLabRt 
			end
		  end
		  Else If @mCmCtg = 'T' 
		  begin
			insert into #wRsOldLabRt 
				Select LrCmCtg, LrCmCd,LrMCd, LrSCd, LrFrWt, LrToWt  from LabRt 
				where LrMCd=@mLabMCd and LrSCd=@mLabSCd and LrCmCurCd=@mCmCurCd 
				and LrCmCtg= 'T' and LrCmCd=@mCmCd and LrFrWt<= convert(varchar,@mOldGldAsWt) and LrToWt>= convert(varchar,@mOldGldAsWt) 
		  
			insert into #wRsNewLabRt 
				Select LrCmCtg, LrCmCd,LrMCd, LrSCd, LrFrWt, LrToWt  from LabRt 
				where LrMCd=@mLabMCd and LrSCd=@mLabSCd and LrCmCurCd=@mCmCurCd 
				and LrCmCtg='T' and LrCmCd=@mCmCd and LrFrWt<= convert(varchar,@mGldAsWt) and LrToWt>= convert(varchar,@mGldAsWt) 
		  end
		else
		begin
		  insert into #wRsOldLabRt 
			Select LrCmCtg, LrCmCd,LrMCd, LrSCd, LrFrWt, LrToWt  from LabRt 
			where LrMCd=@mLabMCd and LrSCd=@mLabSCd and LrCmCurCd=@mCmCurCd 
			and LrCmCtg=@mCmCtg and LrCmCd=@ctSelfCmCd and LrFrWt<= convert(varchar,@mOldGldAsWt) and LrToWt>= convert(varchar,@mOldGldAsWt) 
		  
		  insert into #wRsNewLabRt 
			Select LrCmCtg, LrCmCd,LrMCd, LrSCd, LrFrWt, LrToWt from LabRt 
			where LrMCd=@mLabMCd and LrSCd=@mLabSCd and LrCmCurCd=@mCmCurCd 
			and LrCmCtg=@mCmCtg and LrCmCd=@ctSelfCmCd and LrFrWt<= convert(varchar,@mGldAsWt) and LrToWt>= convert(varchar,@mGldAsWt) 
		end
		
		select @wOldCnt= COUNT(*) from #wRsOldLabRt 
		select @wNewCnt= COUNT(*) from #wRsNewLabRt 
		declare @LrCmCtGOld varchar(2), @LrCmCtgNew varchar(2)
		declare @LrCmCdOld varchar(8), @LrCmCdNew varchar(8) 
		declare @LrMCdOld varchar(5), @LrMCdNew varchar(5)
		declare @LrSCdOld varchar(8), @LrSCdNew varchar(8)
		declare @LrFrWtOld decimal(10,3), @LrFrWtNew decimal(10,3)
		declare @LrToWtOld decimal(10,3), @LrToWtNew decimal(10,3)
		
		select @LrCmCtGOld = LrCmCtg from #wRsOldLabRt 
		select @LrCmCtgNew = LrCmCtg from #wRsNewLabRt 
		select @LrCmCdOld = LrCmCd from #wRsOldLabRt 
		select @LrCmCdNew = LrCmCd from #wRsNewLabRt 
		select @LrMCdOld = LrMCd from #wRsOldLabRt 
		select @LrMCdNew = LrMCd from #wRsNewLabRt 
		select @LrSCdOld = LrSCd from #wRsOldLabRt 
		select @LrSCdNew = LrSCd from #wRsNewLabRt 
		select @LrFrWtOld = LrFrWt from #wRsOldLabRt 
		select @LrFrWtNew = LrFrWt from #wRsNewLabRt 
		select @LrToWtOld = LrToWt from #wRsOldLabRt 
		select @LrToWtNew = LrToWt from #wRsNewLabRt 
		
		If @wOldCnt > 0 And @wNewCnt > 0 
		begin
		  if @LrCmCtGOld = @LrCmCtgNew And @LrCmCdOld = @LrCmCdNew And @LrMCdOld = @LrMCdNew And @LrSCdOld = @LrSCdNew And @LrFrWtOld = @LrFrWtNew And @LrToWtOld = @LrToWtNew 
			select @mWtRngChg = 'F'
		  Else
			select @mWtRngChg = 'T'
       	end
       	Else
       	begin
		  If @wOldCnt > 0 
			select @mWtRngChg = 'F'
		  Else
			select @mWtRngChg = 'T'
		end
	  end
	  else
		select @mWtRngChg = 'F'		
	  
	end
    
exec sp_executesql @GetLabRt,
						N'@wRmRt decimal(10,3) output',
						@wRmRt=@wRmRt output
select @mRt=isnull(@wRmRt ,0)
return 1
End

GOGO

ALTER Procedure [dbo].[ForCpy_GetRmRt] 
	(@mCmCd varchar(8), @mRmCd varchar(16), @mLn1 decimal(8,3), @mLn2 decimal(8,3), 
    @mWtPerDia decimal(8,3), @mOpt As varchar(1), @mLme decimal(10,3), @mCmCtg As char(1)='C',
    @mHistCmCtg char(1) ='', @mHistCmCd varchar(8)='', @mHistYyyyMm decimal(8,0),                         
    @mCmCurCd varchar(8), @mCmLkUpRmRt varchar(8), @mPrtKey char(1), @mRt as decimal(10,3) out)
as
begin

declare @wRmRt as decimal(10,3)
Declare @wRmCtg varchar(2), @wRmSCtg varchar(5)
Declare @ctselfcocd varchar(8)
declare @ctselfcmcd varchar(8)
declare @ErrMsg varchar(500)
Declare @wRtBy varchar(2), @wRt varchar(10), @wInc decimal(10,4), @wCnd varchar(100), @wRtByForCostRt As char(1),
  @wRtChrtByPtr varchar(2), @wRtChrtByBs varchar(2), @wcndForCostRt varchar(100),
  @wCmSeekZSelfRt bit,  @wInp decimal(5,3),  @wFrLn varchar(8), @wToLn varchar(10)
declare @wCommand nvarchar(max)
  
  SELECT @ctselfcocd='ZZZ'
  SELECT @ctSelfCmCd= 'ZSELF'

  If (@mOpt <> 'C') And (@mOpt <> 'S') 
	select 0

  If (@mCmCtg <> 'C') And (@mCmCtg <> 'S') 
	select 0

  If @mCmCurCd='' 
  begin
	select @mCmCurCd = CmCurCd from CustMst where CmCtg= @mCmCtg  and CmCd= @mCmCd 
  end
  --6.1-13 seek from custmst is removed  
  --If @mCmLkUpRmRt = '' 
  --begin
  --  select @mCmLkUpRmRt = CmLkUpRmRt from CustMst where CmCtg= @mCmCtg and CmCd= @mCmCd
  --End
   
  select @wCmSeekZSelfRt = 1 where exists (Select 'x' from CustMst where CmCtg= @mCmCtg and CmCd= @mCmCd and CmSeekZSelfRt='Y')
  
  select @wRmCtg = RmCtg ,@wRmSctg=RmSctg from RmMst where RMCd=@mRmCd 
  If @wRmCtg = 'G' Or @wRmCtg = 'P' Or @wRmCtg = 'S' Or @wRmCtg = 'L' select 0

  declare @ws_RndOff As char(1)
  select @ws_RndOff = (select case when exists((Select 'x' from Head  Join Param on PTyp='CPYRT' and PMCd=HOrdRtRndOffRmCtg Where HCoCd=@ctselfcocd 
											and hCd=@ctSelfCmCd and ','+PDesc225+',' like '%,' + @wRmCtg + ',%' )) then  0 else 3 end)
  
    
  If(@mHistCmCtg IS NULL OR @mHistCmCtg = '') Or @mHistCmCtg <> 'P' 
  begin
    select @wRtChrtByPtr = 'P'  from RmRt where RrTcTyp= 'PTR' and RrCmCtg= @mCmCtg 
                 And RrCmCd = @mCmCd and RrCtg= @wRmCtg and 
                 RrSCtg= @wRmSCtg and RrSTWGrp= '' and RrCd= '' and RrDmCtg= '' 
                 and RrLsCtg= '' and RrLabMCd= '' and RrFrLn= 0 and RrToLn= 0 
	select @wRtChrtByPtr =isnull(@wRtChrtByPtr,'')
	

    select @wRmCtg
	select @wRmSctg
	select @wRtChrtByBs = 'BS' from RmRt where RrTcTyp= 'BS' and RrCmCtg= @mCmCtg 
                 And RrCmCd = @mCmCd and RrCtg= @wRmCtg and RrSCtg= @wRmSCtg and RrSTWGrp= '' and RrCd= '' and RrDmCtg= '' 
                 and RrLsCtg= '' and RrLabMCd= '' and RrFrLn= 0 and RrToLn= 0

	
	select @wRtChrtByBs =isnull(@wRtChrtByBs ,'')
  End	

  select @wRtBy = PValue from Param where PTyp= 'RMSCTG' and PMCd= @wRmCtg and PSCd= @wRmSCtg  
  select @wRtByForCostRt = @wRtBy	
  
  If @wRtChrtByPtr <> '' 
    select @wRtBy = @wRtChrtByPtr
  Else
	If @wRtChrtByBs <> '' 
		select @wRtBy = @wRtChrtByBs
 

  IF(@mHistCmCtg IS NULL OR @mHistCmCtg = '')
    select @wRt = case when @mOpt = 'S' then 'RrSalRt' else 'RrCstRt' end
  Else
    select @wRt = case when @mOpt = 'S' then 'RhSalRt' else 'RhCstRt' end

  If @mCmCtg = 'S' And @mOpt = 'C' select @mCmCtg = 'C'


  If @mOpt ='S' 
	begin
    select @wInc = RrSalRt from RmRt where RrTcTyp= 'INC' and RrCmCtg= @mCmCtg and 
           RrCtg= @wRmCtg and RrSCtg= @wRmSCtg  and RrCmCd= @mCmCd 
    If(@wInc IS NULL OR @wInc = 0)	
      select @wInc = RrSalRt from RmRt where RrTcTyp= 'INC' and RrCmCtg= @mCmCtg and 
           RrCtg= @wRmCtg  and RrSCtg= ''  and RrCmCd= @mCmCd
    If(@wInc IS NULL OR @wInc = 0)	 
      select @wInc = RrSalRt from RmRt where RrTcTyp= 'INC' and RrCmCtg= @mCmCtg and 
           RrCtg= @wRmCtg and RrSCtg= @wRmSCtg and RrCmCd= @ctSelfCmCd 
	If(@wInc IS NULL OR @wInc = 0)	 	
      select @wInc = RrSalRt from RmRt where RrTcTyp= 'INC' and RrCmCtg= @mCmCtg and            
           RrCtg= @wRmCtg and RrSCtg='' and RrCmCd= @ctSelfCmCd 
	If @wInc IS NULL 
		select @wInc = 0	
	end 
  Else
    select @wInc = 0

  If @mOpt = 'S' 
	begin
    select @wInp= RrSalRt from RmRt where RrTcTyp= 'INP' and RrCmCtg= 'P' and 
           RrCtg=@wRmCtg and RrSCtg= @wRmSCtg and RrCmCd=@mCmLkUpRmRt 
    If(@wInp IS NULL OR @wInp = 0)	
      select @wInp =RrSalRt from RmRt where RrTcTyp= 'INP' and RrCmCtg= 'P' and 
           RrCtg= @wRmCtg and RrSCtg= ''  and RrCmCd= @mCmLkUpRmRt 
	If @wInp IS NULL 
		select @wInp = 0
	end  
  Else
    select @wInp = 0

  
  IF(@mHistCmCtg IS NULL OR @mHistCmCtg = '')
	begin
		select @wFrLn = 'RrFrLn'
		select @wToLn = 'RrToLn'
	end
  Else
	begin
		select @wFrLn = 'RhFrLn'
		select @wToLn = 'RhToLn'
	End

  if @wRtBy='S' 
	begin
		If @wRmCtg = 'X'  select @mLn1 = @mLme
		select @wCnd ='  Round(' + @wFrLn+ ', 4) <= Round(' + convert(varchar,@mLn1) + ' , 3) And Round(' + @wToLn + ', 4) >= Round(' + convert(varchar,@mLn1) + ' , 3) and '    
	end
  else if @wRtBy ='W' or @wRtBy='P' 
	select @wCnd =' Round(' + @wFrLn + ', 4) <= Round(' + convert(varchar,@mWtPerDia) + ', 4) And Round(' + @wToLn + ', 4) >= Round(' + convert(varchar,@mWtPerDia) + ', 4) and '
  else if @wRtBy = 'BS'   
	select @wCnd = ' Round(' + @wFrLn + ', 4) = Round(' + convert(varchar,@mLn1) + ', 3) And Round(' + @wToLn + ', 4) = Round(' + + convert(varchar,@mLn2) + ', 3) and '
  else
	select @wCnd =' '    
	
  if @wRtByForCostRt='S'
	begin
		If @wRmCtg = 'X' select @mLn1 = @mLme
		select @wcndForCostRt = ' Round(' + @wFrLn + ', 4) <= Round(' + convert(varchar,@mLn1) + ', 3) And Round(' + @wToLn + ', 4) >= Round(' + convert(varchar,@mLn1) + ', 3) and '
	end
  else if @wRtByForCostRt in ('W', 'P')
    select @wcndForCostRt = ' Round(' + @wFrLn + ', 4) <= Round(' + convert(varchar,@mWtPerDia) + ', 4) And Round(' + @wToLn + ', 4) >= Round(' + convert(varchar,@mWtPerDia) + ', 4) and '
  else if @wRtByForCostRt = 'BS'
    select @wcndForCostRt = ' Round(' + @wFrLn + ', 4) = Round(' + convert(varchar,@mLn1) + ', 3) And Round(' + @wToLn +', 4) = Round(' + convert(varchar,@mLn2) + ', 3) and '
  else 
	select @wcndForCostRt = ' '

  Declare @wAccessoriesRmIncFac varchar(max)
  SELECT @WRTCHRTBYPTR
  SELECT @WRTCHRTBYBS 

  If (@wRtChrtByPtr = '' And @wRtChrtByBs = '' ) 
  begin	
	If(@mHistCmCtg <> '')	
	begin
		Select @wCommand='Select 
						         @wRmRt= isnull((Select ' + @wRt + ' from RmRtHist where ' +
								  'RhYyyyMm=' + convert(varchar,@mHistYyyyMm) + ' and RhTcTyp=''RM'' and ' +
								  'RhCtg=''' + @wRmCtg + ''' and RhSCtg=''' +  @wRmSCtg + '''  and  ' + 
								  'RhCd=''' + @mRmCd + ''' and '+ @wCnd +'RhCmCtg=''' + @mHistCmCtg + ''' and ' + 
								  'RhCmCd=''' + @mHistCmCd + ''' and RhCmCurCd=''' + @mCmCurCd + ''' and '+ @wRt+' <> 0),' + 					  
								  case when(@wCmSeekZSelfRt = 1 Or @mOpt = 'C') then 
								  'Convert(Decimal(14,' +case when @wInc = 0 then '3' else @ws_RndOff end + '),' +
								  'IsNull((Select ' +@wRt + ' from RmRtHist where ' + 
								  'RhYyyyMm=' + convert(varchar,@mHistYyyyMm) + ' and RhTcTyp= ''RM'' and  
								  RhCtg=''' + @wRmCtg + ''' and RhSCtg=''' + @wRmSCtg + ''' and  
								  RhCd=''' + @mRmCd + ''' and ' + @wCnd +' RhCmCtg= ''C'' and RhCmCd =''' + @ctSelfCmCd + ''' and 
								  RhCmCurCd=''' + @mCmCurCd + ''' and ' + 
								  @wRt + ' <> 0)*(1 +' + convert(varchar,@wInc) + ' / 100) ,0))' else '0' end + ')' 
	end
	Else
	begin	  
		select @wAccessoriesRmIncFac =										
										'(case when ''' + @wRmCtg + ''' = ''X'' then ((' + convert(varchar,@mLme) + '-RrFrLn) * ' +
										'(case when ''' + @mOpt + ''' = ''C'' then RrFixMinTol else RrFixMaxTol end)  ) else 0 end) '
															         
		select @wCommand='Select @wRmRt=' + 
			     'isnull((Select ' + @wRt + '+' + @wAccessoriesRmIncFac + 
                 ' from RmRt where RrTcTyp=''RM'' and RrCtg=''' + @wRmCtg + ''' and RrSCtg=''' + @wRmSCtg + ''' and 
				 RrCd=''' + @mRmCd + ''' and ' + @wCnd + ' RrCmCtg= ''P'' and RrCmCd ='''+  @mCmLkUpRmRt + ''' and 
				 RrCmCurCd=''' + @mCmCurCd + ''' and ' +@wRt +  '<> 0)* (1 + '  + convert(varchar,@wInp) + ' / 100) ,  ' +					 				 
                 'isnull((Select ' + @wRt  + '+' + @wAccessoriesRmIncFac + 
                 ' from RmRt where RrTcTyp=''RM'' and RrCtg=''' + @wRmCtg + ''' and RrSCtg=''' + @wRmSCtg + ''' and  
                 RrCd=''' + @mRmCd + ''' and '+@wCnd + ' RrCmCtg=''' +  @mCmCtg + ''' and 
                 RrCmCd =''' + @mCmCd + ''' and RrCmCurCd=''' + @mCmCurCd + ''' and ' + @wRt + ' <> 0) ,' + 
                 ' ' + (case when @wCmSeekZSelfRt =1 Or @mOpt = 'C' 
				 then 'Convert(Decimal(14, '+ case when @wInc = 0 then '3' else @ws_RndOff end +'),' 
				 +'IsNull((Select ' + @wRt + '+' + @wAccessoriesRmIncFac +					
                 ' from RmRt where RrTcTyp= ''RM'' and RrCtg=''' + @wRmCtg + ''' and RrSCtg=''' + @wRmSCtg + ''' and 
                 RrCd=''' + @mRmCd + ''' and '+ @wCnd + ' RrCmCtg=''' + @mCmCtg + ''' and 
                 RrCmCd =''' + @ctSelfCmCd + ''' and RrCmCurCd=''' +  @mCmCurCd + ''' and '                                    
                 +@wRt + ' <> 0)*(1 +'  + convert(varchar, @wInc) + ' / 100) , 0))'  else '0' END )+ '))'
	End
  End
  Else If (@wRtChrtByPtr = 'P' Or @wRtChrtByBs = 'BS')
  begin	
    If(@mHistCmCtg <> '')
    begin
      If (@mOpt = 'C')	  
        select @wCommand='Select @wRmRt=' + @wRt + ' from RmRtHist  
                where RhYyyyMm=' + convert(varchar,@mHistYyyyMm) + ' and RhTcTyp=''RM'' and 
                RhCtg=''' + @wRmCtg + ''' and RhSCtg=''' + @wRmSCtg + ''' and 
                RhCd=''' + @mRmCd + ''' and ' + @wcndForCostRt + ' RhCmCtg= ''C'' and RhCmCd =''' + 
                @ctSelfCmCd + ''' and RhCmCurCd=''' + @mCmCurCd + ''' and ' + @wRt + ' <> 0'
      Else	  
        select @wCommand='Select @wRmRt=' + @wRt + ' from RmRtHist 
                where RhYyyyMm=' + convert(varchar,@mHistYyyyMm) + ' and RhTcTyp= ''RM'' and 
                RhCtg=''' + @wRmCtg + ''' and RhSCtg=''' + @wRmSCtg + ''' and 
                RhCd=''' + @mRmCd + ''' and ' + @wCnd + ' RhCmCtg= ''C'' and RhCmCd =''' + 
                @mCmCd + ''' and RhCmCurCd=''' + @mCmCurCd + ''' and ' + @wRt + ' <> 0'
	End
	else
  
	begin
    If (@mOpt = 'C') 
      select @wCommand='select @wRmRt=isnull((Select  '+ @wRt + ' from RmRt where RrTcTyp=''RM'' and 
				RrCtg='''+ @wRmCtg +''' and RrSCtg='''+ @wRmSCtg +''' and 
                RrCd='''+ @mRmCd +''' and '+ @wCnd + ' RrCmCtg='''+ @mCmCtg +''' and 
                RrCmCd ='''+ @mCmCd +''' and RrCmCurCd='''+ @mCmCurCd +''' and ' +@wRt + ' <> 0),
                isnull((Select ' + @wRt + ' from RmRt where RrTcTyp= ''RM'' and 
				RrCtg='''+ @wRmCtg +''' and RrSCtg=''' + @wRmSCtg +''' and 
				RrCd='''+ @mRmCd +''' and ' + @wcndForCostRt + ' RrCmCtg='''+ @mCmCtg +''' and RrCmCd ='''+ @ctSelfCmCd +''' and 
				RrCmCurCd='''+ @mCmCurCd +''' and '+ @wRt + ' <> 0),0))'
    Else				
     select @wCommand='Select @wRmRt= '+ @wRt +' from RmRt where RrTcTyp= ''RM'' and 
              RrCtg=''' + @wRmCtg + ''' and RrSCtg=''' + @wRmSCtg + ''' and 
              RrCd=''' + @mRmCd + ''' and ' + @wCnd + ' RrCmCtg=''' + @mCmCtg + ''' and RrCmCd =''' + @mCmCd + ''' and 
              RrCmCurCd=''' + @mCmCurCd + ''' and ' + @wRt + ' <> 0 '               
    End
  
  end
  select 'Command:'+isnull(@wCommand ,'')
  BEGIN TRY

  exec sp_executesql @wcommand,
						N'@mCmCd varchar(8), 
						@mRmCd varchar(16), 
                        @mLn1 decimal(8,3), 
						@mLn2 decimal(8,3), 
                        @mWtPerDia decimal(8,3), 
					    @mOpt As varchar(1),                         
					    @mLme decimal(10,3), 
						@mCmCtg As char(1),
                        @mHistCmCtg char(1) , 
						@mHistCmCd varchar(8),
                        @mHistYyyyMm decimal(8,0),                         
						@mCmCurCd varchar(8), 
                        @mCmLkUpRmRt varchar(8),                         
						@mPrtKey char(1),						
						@wRmCtg char(2),
						@wRmSCtg varchar(5),
						@wInp decimal(5,3),  
						@wRmRt decimal(10,3) output'
						,@mCmCd =@mCmCd, 
						@mRmCd =@mRmCd, 
                        @mLn1 =@mLn1, 
						@mLn2 =@mLn2, 
						@mWtPerDia =@mWtPerDia, 
						@mOpt =@mOpt,                         
						@mLme =@mLme, 
						@mCmCtg =@mCmCtg,
                        @mHistCmCtg =@mHistCmCtg, 
						@mHistCmCd =@mHistCmCd,
                        @mHistYyyyMm =@mHistYyyyMm,                         
						@mCmCurCd =@mCmCurCd, 
                        @mCmLkUpRmRt =@mCmLkuPRmRt,                         
						@mPrtKey =@mPrtKey,
						@wRmCtg=@wRmCtg,
						@wRmSCtg=@wRmSCtg,
						@wInp=@wInp,
						@wRmRt=@wRmRt output
						END TRY
						BEGIN CATCH
						 SELECT ERROR_NUMBER() AS ErrorNumber
         ,ERROR_SEVERITY() AS ErrorSeverity
         ,ERROR_STATE() AS ErrorState
         ,ERROR_PROCEDURE() AS ErrorProcedure
         ,ERROR_LINE() AS ErrorLine
         ,ERROR_MESSAGE() AS ErrorMessage
         END CATCH

Select @mrt= isnull(@wrmrt ,0)
RETURN @mrt
END

GOGO


