 	select @row= count('x') from inserted where RrTcTyp in ('RM','IPD') and RrCtg <>'X' and RrCtg <>'G' and RrCtg <>'P' and RrCtg <>'S' and RrCtg <>'L' and RrFixMaxTol> 0   		
